struct ScoreJob : IJob
{
    [ReadOnly] public NativeArray<int> kills;
    public NativeReference<int> total;
    public string playerName;
    public void Execute()
    {
        int sum = 0;
        for (int i = 0; i < kills.Length; i++) sum += kills[i];
        total.Value = sum;
    }
}

