using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;
using UnityEngine;

[BurstCompile]
struct VelocityJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> targets;
    [ReadOnly] public NativeArray<float3> positions;
    public NativeArray<float3> velocities;
    public void Execute(int i) => velocities[i] = math.normalizesafe(targets[i] - positions[i]);
}

[BurstCompile]
struct IntegrateJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> velocities;
    public NativeArray<float3> positions;
    public float dt;
    public void Execute(int i) => positions[i] += velocities[i] * dt;
}

public class Movers : MonoBehaviour
{
    NativeArray<float3> targets, positions, velocities;   // Persistent, see Awake
    JobHandle handle;
    void Update()
    {
        var v = new VelocityJob { targets = targets, positions = positions, velocities = velocities }
            .Schedule(positions.Length, 64);
        handle = new IntegrateJob { velocities = velocities, positions = positions, dt = Time.deltaTime }
            .Schedule(positions.Length, 64, v);   // runs after VelocityJob, no wait
        JobHandle.ScheduleBatchedJobs();          // wake the workers now
    }
    void LateUpdate() => handle.Complete();       // the whole chain is done here
}

