using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

struct Unit
{
    public float3 position;
    public quaternion rotation;
    public float damage, armor, health;
}

[BurstCompile]
struct DamageJob : IJobFor
{
    public NativeArray<Unit> units;
    public void Execute(int i)
    {
        Unit u = units[i];
        if (u.armor > 0f) u.health -= u.damage * 0.5f;
        else u.health -= u.damage;
        units[i] = u;
    }
}

