using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

// SoA: one array per field instead of an array of Unit structs;
// position and rotation live in arrays of their own for other jobs
// this job reads damage and armor and writes health, nothing else

[BurstCompile]
struct DamageJob : IJobFor
{
    [ReadOnly] public NativeArray<float> damage;
    [ReadOnly] public NativeArray<float> armor;
    public NativeArray<float> health;

    public void Execute(int i)
    {
        float full = damage[i];
        // both values are computed, the mask picks one: no branch
        float hit = math.select(full, full * 0.5f, armor[i] > 0f);
        health[i] -= hit;
    }
}

